"""Freeze author hashes only after both AI HL author audits have passed."""
from pathlib import Path
import json,hashlib,collections
ROOT=Path(__file__).resolve().parents[2]
D=ROOT/'docs/ib-expansion-reviews'
audit=json.loads((D/'ai-hl-author-audit.json').read_text(encoding='utf8'))
numeric=json.loads((D/'ai-hl-numeric-audit.json').read_text(encoding='utf8'))
ledger=json.loads((D/'ai-hl-author-ledger.json').read_text(encoding='utf8'))
assert audit['records']==numeric['records']==len(ledger)==500
assert not audit['errors'] and numeric['status']=='passed'
digest=lambda b:hashlib.sha256(b).hexdigest()
questions=[];files=[]
for p in sorted((ROOT/'content/ib/math-ai-hl').glob('*.json')):
 data=p.read_bytes();sha=digest(data);assert sha==numeric['bankHashes'][p.name]
 assert sha==next(x['sha256'] for x in audit['topics'] if x['path'].endswith('/'+p.name))
 assert b'\r' not in data
 qs=json.loads(data);questions+=qs
 files.append({'path':str(p.relative_to(ROOT)).replace('\\','/'),'count':len(qs),'sha256':sha})
assert len({r['family'] for r in ledger})==125
manifest={'course':'math-ai-hl','authorStatus':'frozen-for-independent-review','courseFirstAssessment':2021,'courseFinalAssessment':2028,'revised2029CourseUsed':False,'officialSources':[
 {'role':'syllabus scope','url':'https://ibo.org/globalassets/new-structure/university-admission/pdfs/dp-mathematics-applications-and-interpretation-guide-en.pdf'},
 {'role':'assessment conventions only; no copied questions','url':'https://www.ibo.org/globalassets/new-structure/university-admission/pdfs/dp-mathematics-applications-and-interpretation-specimen-papers-en.pdf'}],
 'records':500,'families':125,'variantsPerFamily':4,'allCalculator':True,'ahlPrimaryRecords':sum(q['level']=='ahl' for q in questions),'investigations12to20Marks':sum(12<=q['marks']<=20 for q in questions),'files':files,'scopeLedgerSha256':digest((D/'ai-hl-author-ledger.json').read_bytes()),'numericAuditSha256':digest((D/'ai-hl-numeric-audit.json').read_bytes()),'structuralAuditSha256':digest((D/'ai-hl-author-audit.json').read_bytes()),'uniqueDiagramsRendered':audit['uniqueDiagramsRendered'],'diagramUses':audit['diagramUses'],'visualReview':'All four contact sheets inspected; integer ticks, explicit original point coordinates, true origin axes, equal scales for Argand/geometry, network edge labels and private solution-only coordinates checked.',
 'recordHashes':[{'id':q['id'],'sha256':digest(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()),'scopeStatus':'author-confirmed','numericStatus':'passed','figureStatus':'rendered-and-author-inspected' if q.get('diagramSvg') or q.get('markSchemeDiagramSvg') else 'not-required'} for q in sorted(questions,key=lambda q:q['id'])]}
(D/'ai-hl-author-freeze.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf8',newline='\n')
lines=['# AI HL author freeze','', '500 original practice questions are complete: 100 in each of the five course topics, with 25 distinct families per topic and four variants per family. All require a calculator. The bank targets the first-assessment-2021 course through its final 2028 assessment, not the revised 2029 course.','',f"The bank includes {manifest['ahlPrimaryRecords']} records with AHL primary scope and {manifest['investigations12to20Marks']} investigations carrying 12–14 marks. These investigate modelling assumptions, uncertainty, interpretation, decisions and numerical methods alongside calculations.",'', 'The official guide and specimen were read for scope and assessment conventions. All wording, numerical data and figures were independently authored; no published question or markscheme was copied.','', '## Verification','',f"- Structural, numbering, source, per-part mark-total, one-point criterion, calculator, unique-family and SVG-safety checks passed for all 500 records.",f"- {audit['formulaeValidated']} formula occurrences rendered through KaTeX without errors.",f"- A separate numerical audit, which does not import the generator, checked all 500 records through {numeric['checks']} ledger fields. Lists and vectors were checked componentwise. It uses direct probability sums, independent t/normal probability evaluations, iteration, residual equations, quadrature, normal-equation least squares and matrix exponentials.",f"- All {audit['diagramUses']} diagram uses ({audit['uniqueDiagramsRendered']} unique SVGs) were rasterized. Four contact sheets were visually inspected. Original diagram coordinates and networks are public; rotated solution coordinates are present only in private markscheme figures.",'- Decimal ROUND_HALF_UP preserves three-significant-figure trailing zeros. Calculations retain unrounded working. All bank and author files use UTF-8 with LF endings.','- Scope rationale and unrounded results are recorded for every question in `ai-hl-author-ledger.json`. Exact bank and per-record hashes are in `ai-hl-author-freeze.json`.','- This is author verification. Independent cross-review and app/media/deployment checks are owned by the integrating agent.','', '## Scope decisions','', '- No complex-number roots, general proof of vector-product properties, Runge–Kutta methods, logistic differential-equation derivation, or complex-eigenvalue exact ODE solutions are required.','- Diagonalization uses 2 by 2 matrices with distinct real eigenvalues. Complex/imaginary phase portraits are assessed qualitatively.','- Confidence intervals and mean tests use t when population SD is unknown. Pooled two-sample tests state the equal-variance assumption. Matched pairs analyze a single sample of differences.','- Binomial/Poisson tests are one-tailed; their discrete critical regions use actual Type I probability strictly below the nominal level.','- Chi-square goodness-of-fit accounts for the fitted parameter and all expected category counts exceed 5. Nonlinear regression states whether it minimizes residuals in log or original output units.','- Column Markov state conventions and simultaneous old-state Euler updates are explicit.','', '## Reproduction','', 'Run `ai_hl_build.py` (optionally `--limit 80` for the 400-record checkpoint), `ai_hl_numeric_audit.py`, `ai-hl-audit.mjs`, and finally `ai_hl_signoff.py` from this authoring directory or the repository root. Python uses the existing `work/aa-sl-deps` scientific dependencies; Node uses the repository dependencies.','', '## Families','']
for filename in ['number-algebra','functions','geometry-trigonometry','statistics-probability','calculus']:
 qs=sorted([q for q in questions if q['topicId']==filename],key=lambda q:q['number'])
 lines.extend(['### '+filename,'','| Questions | Family | Primary scope | Marks |','|---|---|---|---|'])
 for i in range(0,100,4):
  q=qs[i];lines.append(f"| {i+1}–{i+4} | {q['subtopic']} | {q['syllabusCode']} | {q['marks']} |")
 lines.append('')
(D/'ai-hl-author-signoff.md').write_text('\n'.join(lines)+'\n',encoding='utf8',newline='\n')
print(json.dumps({'status':manifest['authorStatus'],'records':500,'fileHashes':files,'freezeSha256':digest((D/'ai-hl-author-freeze.json').read_bytes())}))
